{"description":"Extract command sessions from bottom OCR","cmd":"cat > /app/extract_sessions.py <<'PY'
import glob, os, re

files=sorted(glob.glob('/app/bottom_ocr/b*.txt'))

def last_prompt(lines):
    prompts=[]
    for l in lines:
        s=l.strip()
        if s.startswith('>') and s != '>':
            txt=s[1:].strip()
            # strip trailing underscore artifact often means cursor
            prompts.append(txt)
    if not prompts:
        return None
    return prompts[-1]

sessions=[]  # each dict(start, end, list_texts, final)
active=None

def flush(final, end):
    if final is not None and final.strip():
        sessions.append({'start':active['start'], 'end':end, 'texts':active['texts'], 'final':final})

for f in files:
    frame=int(os.path.basename(f)[1:6])
    txt=open(f).read().splitlines()
    cur=last_prompt(txt)
    if cur is None:
        if active is not None:
            # flush active session final as last text if not already
            flush(active['final'], active['end'])
            active=None
    else:
        if active is None:
            active={'start':frame,'texts':[cur], 'final':cur}
        else:
            prev=active['final']
            # Is cur a continuation (prefix extension) of prev or prev extension of cur?
            # Normalize by lower for check
            pl=prev.lower(); cl=cur.lower()
            cont = pl==cl or pl.startswith(cl) or cl.startswith(pl) or pl in cl or cl in pl
            if not cont:
                # new command started
                flush(active['final'], frame-3)
                active={'start':frame,'texts':[cur], 'final':cur}
            else:
                active['texts'].append(cur)
                # take longer text as final? If cur longer, final=cur; else keep prev (handle backspace)
                if len(cur)>len(active['final']):
                    active['final']=cur
                # else keep

if active is not None:
    flush(active['final'], 999999)

print('total sessions',len(sessions))
for i,s in enumerate(sessions,1):
    print(i, s['start'], s['end'], repr(s['final']), '| variants:', ','.join(s['texts'][:10]))
