import glob, os, re

files=sorted(glob.glob('/app/bottom_ocr/b*.txt'))

def last_prompt(lines):
    prompts=[]
    for l in lines:
        s=l.strip()
        if s.startswith('>') and s != '>':
            txt=s[1:].strip()
            prompts.append(txt)
    if not prompts:
        return None
    return prompts[-1]

sessions=[]
active=None

def flush(final, end):
    if final is not None and final.strip():
        sessions.append({'start':active['start'], 'end':end, 'texts':active['texts'], 'final':final})

for f in files:
    frame=int(os.path.basename(f)[1:6])
    txt=open(f).read().splitlines()
    cur=last_prompt(txt)
    if cur is None:
        if active is not None:
            flush(active['final'], active.get('end', active['start']))
            active=None
    else:
        if active is None:
            active={'start':frame,'texts':[cur], 'final':cur, 'end':frame}
        else:
            active['end']=frame
            prev=active['final']
            pl=prev.lower(); cl=cur.lower()
            cont = pl==cl or pl.startswith(cl) or cl.startswith(pl) or pl in cl or cl in pl
            if not cont:
                flush(active['final'], frame-3)
                active={'start':frame,'texts':[cur], 'final':cur, 'end':frame}
            else:
                active['texts'].append(cur)
                if len(cur)>len(active['final']):
                    active['final']=cur

if active is not None:
    flush(active['final'], active.get('end', active['start']))

print('total sessions',len(sessions))
for i,s in enumerate(sessions,1):
    print(i, s['start'], s['end'], repr(s['final']), '| variants:', ','.join(s['texts'][:15]))
